export const SAVING_VS_INVESTING_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu menabung",q:"'Menabung' pada dasarnya adalah...",options:["Menyisihkan sebagian uang & menyimpannya di tempat yang aman & mudah diambil, agar nilainya terjaga untuk dipakai nanti","Menghabiskan penghasilan setiap bulan untuk jajan dan hiburan supaya uangnya tidak menganggur dan terasa bermanfaat langsung","Meminjam uang dari orang lain untuk keperluan mendadak lalu mengembalikannya sedikit demi sedikit dari uang saku"],answer:0,explain:"Menabung menekankan keamanan & ketersediaan (likuiditas): uangnya hampir pasti utuh & bisa diambil kapan pun dibutuhkan.",hint:"Menyimpan uang dengan aman & mudah diambil, atau menaruhnya di tempat berisiko?"},
{n:2,type:"mcq",micro:"Apa itu investasi",q:"'Investasi' pada dasarnya adalah...",options:["Menyembunyikan uang di bawah kasur atau di dalam lemari, supaya tidak ada orang lain yang bisa mengambil atau mengetahuinya","Menempatkan uang pada sesuatu (usaha, emas, reksadana, dll.) dengan harapan nilainya tumbuh seiring waktu, sambil menerima adanya risiko naik-turun","Membelanjakan uang untuk barang konsumsi yang cepat habis, dengan harapan barang itu nanti dapat dijual kembali lebih mahal"],answer:1,explain:"Investasi bertujuan pertumbuhan jangka panjang & menerima risiko. Nilainya bisa naik maupun turun sebelum akhirnya (diharapkan) tumbuh.",hint:"Tujuannya menjaga nilai apa adanya, atau menumbuhkannya dengan menerima risiko?"},
{n:3,type:"mcq",micro:"Beda inti",q:"Beda inti menabung & investasi:",options:["Keduanya sama saja, sehingga tidak berbeda dalam tujuan, tingkat risiko, maupun kemudahan mencairkan uang; yang berbeda hanya nama produk di bank","Menabung untung besar tanpa risiko, sedangkan investasi merugi sehingga lebih baik dihindari oleh seluruh anggota keluarga yang ingin uangnya aman","Menabung: prioritas keamanan & mudah diambil, pertumbuhan kecil. Investasi: prioritas pertumbuhan jangka panjang, ada risiko & tak selalu mudah dicairkan"],answer:2,explain:"Keduanya alat berbeda untuk tujuan berbeda. Kebanyakan orang butuh keduanya: tabungan untuk kebutuhan dekat, investasi untuk tujuan jauh.",hint:"Satu mengutamakan aman & cair, satu lagi mengutamakan tumbuh."},
{n:4,type:"mcq",micro:"Tujuan jangka pendek",q:"Uang untuk tujuan yang akan dipakai dalam waktu dekat (mis. bayar sekolah 3 bulan lagi, dana darurat) sebaiknya...",options:["Ditabung di tempat aman & mudah diambil, bukan diinvestasikan pada hal berisiko","Diinvestasikan di kripto supaya cepat berlipat dalam beberapa minggu","Dipinjamkan ke teman dengan bunga agar cepat berlipat dalam waktu singkat"],answer:0,explain:"Untuk kebutuhan dekat, kepastian jumlah jauh lebih penting daripada peluang tumbuh. Investasi berisiko bisa turun tepat saat uangnya dibutuhkan.",hint:"Kalau uang itu dipakai 3 bulan lagi, apakah kamu berani ia turun 20%?"},
{n:5,type:"mcq",micro:"Tujuan jangka panjang",q:"Uang untuk tujuan yang masih sangat jauh (mis. biaya kuliah 10 tahun lagi, masa tua) cocok...",options:["Disimpan tunai di dompet bertahun-tahun, karena uang tunai tidak berubah nilainya dan mudah diambil kapan saja","Sebagian diinvestasikan, karena waktu yang panjang memberi kesempatan pertumbuhan & memulihkan penurunan sementara","Dihabiskan sekarang untuk keinginan yang ada, karena masa depan yang jauh belum perlu dipikirkan atau dipersiapkan"],answer:1,explain:"Makin panjang waktunya, makin besar manfaat pertumbuhan & makin ringan dampak naik-turun jangka pendek.",hint:"Waktu 10 tahun memberi ruang untuk apa?"},
{n:6,type:"mcq",micro:"Risiko & imbal hasil",q:"Hubungan umum antara risiko & potensi imbal hasil (keuntungan):",options:["Imbal hasil yang tinggi datang tanpa risiko, sehingga investasi paling menguntungkan juga paling aman dimasuki","Risiko yang rendah memberi imbal hasil yang tinggi, sehingga pilihan paling aman otomatis paling menguntungkan","Makin tinggi potensi imbal hasil, umumnya makin tinggi pula risikonya (kemungkinan rugi/turun)"],answer:2,explain:"Tidak ada 'untung besar tanpa risiko'. Bila ada yang menjanjikan itu, curigai penipuan.",hint:"Bisakah sesuatu memberi untung besar sekaligus benar-benar aman?"},
{n:7,type:"mcq",micro:"Dana darurat lebih dulu",q:"Sebelum mulai berinvestasi, langkah yang umumnya didahulukan:",options:["Membangun dana darurat (mis. beberapa bulan biaya hidup) di tabungan yang aman & mudah diambil","Langsung menaruh seluruh uang di saham agar cepat berkembang, lalu dana darurat dikumpulkan dari untungnya","Berutang untuk menambah modal investasi, karena hasil investasi dianggap lebih besar dari bunga utangnya"],answer:0,explain:"Dana darurat mencegahmu terpaksa menjual investasi di saat rugi atau berutang saat ada kejutan hidup.",hint:"Apa penyangga yang harus ada sebelum uang 'dikunci' di investasi?"},
{n:8,type:"mcq",micro:"Bunga majemuk yang menguntungkan",q:"Saat menabung/berinvestasi, 'bunga majemuk' berarti...",options:["Kamu hanya mendapat bunga dari setoran awal saja, sedangkan hasil dari tahun-tahun sebelumnya tidak ikut dihitung lagi","Hasil yang kamu peroleh ikut menghasilkan lagi di periode berikutnya, sehingga pertumbuhan makin cepat seiring waktu","Uangmu berkurang sedikit demi sedikit setiap tahun karena hasil yang kamu peroleh dipotong untuk membayar biaya bank"],answer:1,explain:"Bunga majemuk membuat 'uang menghasilkan uang, lalu hasilnya menghasilkan lagi'. Mulai lebih awal memberi efek jauh lebih besar.",hint:"Bunga dihitung dari setoran awal saja, atau dari setoran + hasil sebelumnya?"},
{n:9,type:"order",micro:"Urutan mengelola uang",q:"Urutkan langkah membangun keuangan sebelum & saat mulai berinvestasi.",items:["Buat anggaran: pastikan pengeluaran lebih kecil dari penghasilan","Bangun dana darurat di tabungan aman","Lunasi utang berbunga tinggi","Mulai investasi rutin untuk tujuan jangka panjang, sesuai profil risiko"],answer:[0,1,2,3],explain:"Anggaran surplus → dana darurat → hapus utang mahal → baru investasi jangka panjang. Fondasi dulu, pertumbuhan kemudian.",hint:"Apa fondasi paling dasar sebelum bisa menyisihkan untuk investasi?"},
{n:10,type:"mcq",micro:"Inflasi",q:"'Inflasi' adalah kecenderungan harga barang & jasa naik dari waktu ke waktu, yang berarti...",options:["Harga barang dan jasa tetap dari tahun ke tahun, sehingga uang yang sama bernilai setara di masa depan","Uang yang sama bisa membeli lebih banyak barang tiap tahun, sehingga menyimpan uang tunai makin menguntungkan","Daya beli uang menurun perlahan; Rp100.000 tahun depan biasanya membeli sedikit lebih sedikit daripada hari ini"],answer:2,explain:"Karena inflasi, uang yang hanya didiamkan (mis. di celengan) kehilangan daya beli secara perlahan meski jumlahnya tetap.",hint:"Kalau harga naik tiap tahun, nilai uang yang didiamkan naik atau turun?"},
{n:11,type:"tf",micro:"Butuh keduanya",q:"Benar atau Salah: Kebanyakan orang membutuhkan menabung DAN berinvestasi, karena keduanya melayani tujuan yang berbeda.",answer:true,explain:"Tabungan untuk keamanan & kebutuhan dekat; investasi untuk pertumbuhan & tujuan jauh. Bukan memilih salah satu, melainkan memakai keduanya pada porsinya.",hint:"Apakah kamu harus memilih hanya satu?"},
{n:12,type:"tf",micro:"Investasi = untung pasti?",q:"Benar atau Salah: Investasi selalu memberi keuntungan & tidak mungkin membuat nilainya turun.",answer:false,explain:"Sebaliknya, nilai investasi bisa naik & turun, dan pada jangka pendek bisa merugi. Justru karena ada risiko itulah potensi imbal hasilnya lebih besar daripada menabung.",hint:"Kalau untung dijamin, kenapa disebut 'risiko'?"},
{n:13,type:"mcq",micro:"Likuiditas",q:"'Likuiditas' sebuah aset berarti...",options:["Seberapa mudah & cepat aset itu diubah menjadi uang tunai tanpa kehilangan banyak nilai","Seberapa berat dan besar aset itu saat dipindahkan dari satu tempat ke tempat lain","Seberapa menarik tampilan aset itu bagi calon pembeli yang melihatnya di pasar"],answer:0,explain:"Tabungan sangat likuid (bisa diambil kapan saja). Sebagian investasi kurang likuid (perlu waktu/biaya untuk dicairkan).",hint:"Seberapa cepat kamu bisa mengubahnya jadi uang saat butuh?"},
{n:14,type:"mcq",micro:"Menabung rutin",q:"Kebiasaan menyisihkan sejumlah kecil uang secara rutin (mis. tiap dapat uang jajan/gaji)...",options:["Tidak berguna karena jumlahnya terlalu kecil, sehingga lebih baik menunggu punya uang besar baru mulai menabung","Jauh lebih efektif daripada menunggu 'punya banyak dulu', karena konsistensi + waktu membangun jumlah besar","Hanya berlaku untuk orang berpenghasilan besar, sedangkan pelajar dengan uang saku kecil tidak merasakan manfaatnya"],answer:1,explain:"'Bayar diri sendiri lebih dulu': sisihkan di awal, bukan dari sisa. Kebiasaan kecil yang konsisten mengalahkan niat besar yang jarang.",hint:"Menyisihkan sedikit tiap kali, atau menunggu sampai 'banyak'?"},
{n:15,type:"mcq",micro:"Diversifikasi (dasar)",q:"'Jangan menaruh semua telur dalam satu keranjang' dalam investasi berarti...",options:["Beli satu jenis aset sebanyak mungkin, karena memusatkan uang pada pilihan terbaik memberi hasil paling tinggi","Simpan semua uang di satu perusahaan yang kamu percaya, sebab perusahaan yang bagus kecil kemungkinan bermasalah","Sebar uang ke beberapa jenis aset/tempat, agar kerugian di satu bagian tidak menghancurkan seluruh dana"],answer:2,explain:"Diversifikasi mengurangi risiko: bila satu aset turun, yang lain bisa menahan. Tidak menghapus risiko, tetapi meredamnya.",hint:"Kalau satu keranjang jatuh, lebih baik semua telur di sana atau tersebar?"},
{n:16,type:"mcq",micro:"Contoh instrumen (gagasan)",q:"Contoh tempat menaruh uang, dari yang umumnya lebih aman/stabil ke yang lebih berisiko/berfluktuasi:",options:["Tabungan & deposito → emas → reksadana campuran → saham perusahaan tunggal","Saham perusahaan tunggal → reksadana campuran → emas → tabungan & deposito","Emas → tabungan & deposito → saham perusahaan tunggal → reksadana campuran"],answer:0,explain:"Ini gambaran umum, bukan nasihat: makin ke kanan, potensi tumbuh & potensi turun sama-sama lebih besar.",hint:"Mana yang nilainya paling jarang berubah, mana yang paling sering naik-turun?"},
{n:17,type:"mcq",micro:"Deposito",q:"'Deposito' di bank adalah...",options:["Pinjaman dari bank dengan jangka waktu tertentu & bunga yang kamu bayar, dan harus dilunasi sebelum jatuh tempo agar tidak dikenai denda","Simpanan dengan jangka waktu tertentu & bunga sedikit lebih tinggi dari tabungan biasa, tetapi tidak bisa diambil bebas sebelum jatuh tempo tanpa penalti","Investasi saham berisiko tinggi dengan jangka waktu tertentu & potensi untung besar, tetapi nilainya bisa turun tajam sebelum jatuh tempo"],answer:1,explain:"Deposito lebih ke arah 'menabung plus': relatif aman, imbal hasil kecil, likuiditas terbatas selama jangka waktunya.",hint:"Aman & bunga kecil tapi 'terkunci' sementara — menabung atau berjudi?"},
{n:18,type:"mcq",micro:"Emas",q:"Emas sering dipakai sebagian orang untuk...",options:["Menghasilkan bunga bulanan yang tetap, sehingga pemiliknya menerima tambahan uang tiap bulan tanpa perlu menjualnya","Dijamin naik harganya setiap hari, sehingga pembelinya kecil kemungkinan mengalami kerugian dan tidak perlu memantau","Menyimpan nilai jangka panjang & sebagai pelindung saat mata uang melemah, meski harganya juga bisa naik-turun & tidak memberi 'bunga'"],answer:2,explain:"Emas cenderung mempertahankan daya beli dalam jangka sangat panjang, tetapi berfluktuasi & tidak menghasilkan pendapatan rutin. Ini penjelasan, bukan ajakan membeli.",hint:"Menyimpan nilai jangka panjang, atau memberi penghasilan bulanan pasti?"},
{n:19,type:"mcq",micro:"Waspada 'cepat kaya'",q:"Tawaran investasi yang menjanjikan 'untung 30% per bulan, pasti, tanpa risiko'...",options:["Kemungkinan besar penipuan — imbal hasil setinggi itu yang 'dijamin' tidak realistis & melanggar prinsip risiko-imbal hasil","Kesempatan emas yang harus segera diambil sebelum kuotanya habis, karena tawaran sebesar itu jarang datang dua kali dalam hidup","Hal biasa dalam dunia investasi, sebab banyak investasi resmi yang memang menjamin keuntungan tinggi setiap bulan tanpa risiko"],answer:0,explain:"Ciri penipuan investasi: imbal hasil tetap yang sangat tinggi, 'dijamin', tekanan merekrut orang lain, & legalitas tidak jelas.",hint:"Untung sangat besar + 'pasti' + 'tanpa risiko' = tanda apa?"},
{n:20,type:"open",micro:"Memilah tujuan ke tabungan atau investasi",q:"Seseorang punya 4 tujuan: (a) dana darurat, (b) beli sepeda tahun depan, (c) biaya kuliah 8 tahun lagi, (d) liburan 4 bulan lagi. Untuk tiap tujuan, sebut sebaiknya 'ditabung (aman & likuid)' atau 'sebagian diinvestasikan (jangka panjang)', beserta alasannya.",explain:"Jawaban baik memakai horizon waktu sebagai kunci: tujuan dekat (dana darurat, sepeda 1 tahun, liburan 4 bulan) ditabung agar aman & likuid; tujuan jauh (kuliah 8 tahun) boleh sebagian diinvestasikan untuk pertumbuhan, lalu digeser ke aman saat mendekati waktu pakai.",hint:"Tanyakan: berapa lama lagi uang ini dipakai, dan beranikah nilainya turun sementara?",sample:"(a) Dana darurat → ditabung di tempat aman & mudah diambil. Alasan: harus tersedia sewaktu-waktu dan jumlahnya tidak boleh turun saat dibutuhkan. (b) Sepeda tahun depan → ditabung. Alasan: jangka pendek (~12 bulan); kalau diinvestasikan pada aset berisiko, nilainya bisa turun tepat saat mau dibeli. (c) Biaya kuliah 8 tahun lagi → sebagian bisa diinvestasikan untuk jangka panjang. Alasan: waktu 8 tahun cukup panjang untuk memanfaatkan pertumbuhan dan memulihkan penurunan sementara; mendekati waktu pemakaian, sebaiknya dipindah bertahap ke yang lebih aman. (d) Liburan 4 bulan lagi → ditabung. Alasan: sangat jangka pendek; kepastian jumlah lebih penting daripada peluang tumbuh."},
{n:21,type:"classify",micro:"Menabung vs investasi",q:"Kelompokkan tiap ciri ke 'Lebih menggambarkan MENABUNG' atau 'Lebih menggambarkan INVESTASI'.",items:["Prioritas: uang aman & bisa diambil kapan saja","Prioritas: nilai tumbuh dalam jangka panjang","Nilai bisa naik-turun sebelum akhirnya diharapkan naik","Cocok untuk dana darurat & kebutuhan dalam waktu dekat"],groups:["Lebih menggambarkan MENABUNG","Lebih menggambarkan INVESTASI"],answer:{"Lebih menggambarkan MENABUNG":["Prioritas: uang aman & bisa diambil kapan saja","Cocok untuk dana darurat & kebutuhan dalam waktu dekat"],"Lebih menggambarkan INVESTASI":["Prioritas: nilai tumbuh dalam jangka panjang","Nilai bisa naik-turun sebelum akhirnya diharapkan naik"]},explain:"Menabung = keamanan + likuiditas + tujuan dekat. Investasi = pertumbuhan + risiko fluktuasi + tujuan jauh.",hint:"Mana yang tentang 'aman & cepat diambil', mana yang tentang 'tumbuh tapi naik-turun'?"},
{n:22,type:"mcq",micro:"Horizon waktu menentukan",q:"Faktor paling menentukan apakah sebuah uang cocok diinvestasikan atau sebaiknya ditabung:",options:["Pendapat teman dan saudara tentang produk yang sedang ramai dibicarakan, serta rekomendasi dari media sosial","Berapa lama lagi uang itu akan dibutuhkan (horizon waktu) & seberapa besar kamu sanggup menerima nilainya turun sementara","Tampilan aplikasi bank, kemudahan menu, dan hadiah pendaftaran yang diberikan saat pertama kali membuka rekening"],answer:1,explain:"Horizon pendek → tabungan (kepastian). Horizon panjang + toleransi risiko → sebagian investasi (pertumbuhan).",hint:"Kapan uangnya dipakai, & apakah kamu tahan melihatnya turun sebentar?"},
{n:23,type:"mcq",micro:"Compounding & waktu",q:"Dua orang menabung jumlah sama per bulan dengan hasil yang ikut berbunga. A mulai umur 20, B mulai umur 30. Di umur 60...",options:["B lebih banyak karena mulai belakangan, sehingga uangnya sempat tumbuh lebih cepat per tahun","Keduanya sama saja, karena jumlah setoran total yang ditanam sama besar pada akhir periode","A hampir selalu punya jauh lebih banyak, karena uangnya 'bertumbuh berbunga' 10 tahun lebih lama"],answer:2,explain:"Waktu adalah bahan bakar bunga majemuk. Memulai lebih awal, meski jumlah kecil, sering mengalahkan memulai besar tetapi terlambat.",hint:"Siapa yang memberi waktu lebih lama bagi 'bunga berbunga' untuk bekerja?"},
{n:24,type:"mcq",micro:"Menghitung compounding sederhana",q:"Rp1.000.000 tumbuh 10% per tahun (hasil diinvestasikan ulang). Setelah 2 tahun kira-kira...",options:["Rp1.210.000 (Rp1.100.000 di tahun 1, lalu +10% lagi)","Rp1.200.000 (Rp1.100.000 di tahun 1, lalu +Rp100.000)","Rp990.000 (Rp1.100.000 di tahun 1, lalu −10% lagi)"],answer:0,explain:"Tahun 1: 1.000.000 × 1,1 = 1.100.000. Tahun 2: 1.100.000 × 1,1 = 1.210.000. Ekstra Rp10.000 adalah 'bunga atas bunga'.",hint:"Kalikan dengan 1,1 dua kali, bukan menambah 20% sekaligus."},
{n:25,type:"mcq",micro:"Reksadana (gagasan)",q:"'Reksadana' adalah...",options:["Tabungan bebas risiko yang nilainya dijamin tak turun, cocok untuk menyimpan seluruh dana darurat maupun tujuan jangka pendek, asalkan disetor rutin","Wadah yang mengumpulkan uang banyak orang, dikelola manajer investasi untuk dibelikan beragam aset (saham/obligasi/pasar uang) — memudahkan diversifikasi","Pinjaman berbunga tinggi dari perusahaan keuangan yang harus dilunasi tiap bulan beserta bunga besarnya, dan dikelola oleh manajer pinjaman perusahaan"],answer:1,explain:"Reksadana memungkinkan pemula ikut berinvestasi terdiversifikasi tanpa harus memilih aset satu per satu. Tetap ada risiko & biaya pengelolaan. Ini penjelasan, bukan rekomendasi.",hint:"Uang banyak orang dikumpulkan & dikelola bersama untuk beli beragam aset — apa namanya?"},
{n:26,type:"mcq",micro:"Saham (gagasan)",q:"Membeli 'saham' sebuah perusahaan berarti...",options:["Meminjamkan uang kepada bank dengan imbalan bunga tetap, sehingga nilainya hampir tidak berubah dan risiko turunnya sangat kecil sepanjang waktu","Membeli barang produksi perusahaan itu dengan harga lebih murah, tanpa memiliki bagian perusahaannya, sehingga nilai belanjanya tak naik atau turun","Memiliki sepotong kecil perusahaan itu; nilainya naik-turun mengikuti kinerja & pandangan pasar, berpotensi tumbuh besar tetapi juga bisa turun tajam"],answer:2,explain:"Saham historisnya memberi pertumbuhan jangka panjang yang baik untuk banyak pasar, tetapi sangat fluktuatif jangka pendek. Perlu horizon panjang & diversifikasi. Bukan nasihat beli.",hint:"Memiliki sebagian perusahaan, atau meminjamkan uang?"},
{n:27,type:"tf",micro:"Inflasi menggerus tabungan diam",q:"Benar atau Salah: Uang yang hanya didiamkan tanpa bunga (mis. di celengan) perlahan kehilangan daya beli karena inflasi, meskipun jumlah angkanya tidak berubah.",answer:true,explain:"Rp1.000.000 hari ini & Rp1.000.000 sepuluh tahun lagi jumlahnya sama, tetapi yang kemudian membeli lebih sedikit. Itulah salah satu alasan sebagian uang jangka panjang diinvestasikan.",hint:"Jumlah tetap, tapi harga-harga naik — daya belinya bagaimana?"},
{n:28,type:"mcq",micro:"Biaya & pajak investasi",q:"Saat menilai imbal hasil investasi, yang penting adalah...",options:["Imbal hasil bersih: setelah dikurangi biaya pengelolaan, biaya transaksi, & pajak yang berlaku","Angka imbal hasil 'kotor' yang tertulis besar di brosur promosi, tanpa memperhitungkan biaya yang harus dibayar","Angka yang tertulis di brosur, sebab dalam investasi tidak ada biaya yang mengurangi jumlah yang masuk ke rekeningmu"],answer:0,explain:"Biaya yang tampak kecil (mis. 2% per tahun) bisa memangkas hasil jangka panjang secara signifikan. Bandingkan biaya antar produk sejenis.",hint:"Angka di brosur, atau yang benar-benar kamu terima setelah semua potongan?"},
{n:29,type:"mcq",micro:"Volatilitas jangka pendek",q:"Nilai investasi saham/reksadana saham yang turun 15% dalam sebulan...",options:["Jarang terjadi pada investasi yang dikelola dengan benar, sehingga penurunan seperti itu menandakan adanya kesalahan atau penipuan","Adalah hal normal dalam jangka pendek; yang penting adalah rencana jangka panjang & tidak panik menjual di titik rugi","Berarti uangmu hilang untuk seterusnya, sehingga pilihan terbaik adalah segera menjual semuanya sebelum turun lebih dalam"],answer:1,explain:"Fluktuasi adalah harga dari potensi pertumbuhan. Menjual karena panik saat turun sering mengubah 'penurunan sementara' menjadi 'kerugian permanen'.",hint:"Turun sementara pada horizon panjang: normal atau tanda gagal?"},
{n:30,type:"order",micro:"Menilai tawaran investasi",q:"Urutkan langkah memeriksa apakah sebuah tawaran investasi layak dipercaya.",items:["Cek legalitas: apakah perusahaan & produknya terdaftar/berizin di otoritas yang berwenang","Pahami: uangnya diputar ke mana & dari mana keuntungannya berasal secara masuk akal","Waspadai tanda bahaya: imbal hasil tinggi 'dijamin', tekanan buru-buru, bonus merekrut orang","Kalau ada yang tidak jelas atau terlalu bagus, tolak — lindungi modal lebih penting daripada takut ketinggalan"],answer:[0,1,2,3],explain:"Legalitas → logika keuntungan → tanda bahaya → keputusan. 'Terlalu bagus untuk jadi kenyataan' hampir selalu benar.",hint:"Apa hal pertama yang wajib dicek soal legalitasnya?"},
{n:31,type:"mcq",micro:"Skema Ponzi",q:"'Skema Ponzi' membayar 'keuntungan' investor lama menggunakan...",options:["Keuntungan bisnis yang sah dan besar, dari usaha nyata yang terus berkembang dan membagikan hasil kepada investor","Bantuan dari pemerintah bagi investor kecil, yang dibagikan dari dana negara untuk mendorong masyarakat menabung","Uang setoran investor baru, bukan dari usaha nyata — sehingga pasti runtuh saat aliran anggota baru berhenti"],answer:2,explain:"Ciri: imbal hasil rutin yang mulus & tinggi, fokus merekrut, sulit menarik dana besar. Saat perekrutan melambat, skema kolaps & mayoritas rugi.",hint:"Dari mana uang untuk membayar 'untung' anggota lama?"},
{n:32,type:"tf",micro:"Diversifikasi menghapus risiko?",q:"Benar atau Salah: Diversifikasi (menyebar investasi ke banyak aset) menghilangkan risiko sepenuhnya sehingga mustahil rugi.",answer:false,explain:"Sebaliknya, diversifikasi hanya mengurangi & meredam risiko tertentu, tidak menghapusnya. Pasar secara keseluruhan tetap bisa turun. Tidak ada investasi yang benar-benar bebas risiko.",hint:"Menyebar telur mengurangi kerugian bila satu keranjang jatuh — tapi kalau semua keranjang jatuh?"},
{n:33,type:"mcq",micro:"Dollar-cost averaging (menyicil rutin)",q:"Berinvestasi dengan jumlah tetap secara rutin (mis. tiap bulan), tanpa menebak waktu terbaik, membantu karena...",options:["Kamu otomatis membeli lebih banyak saat harga murah & lebih sedikit saat mahal, serta terhindar dari godaan menebak-nebak pasar","Menjamin kamu terhindar dari kerugian, karena membeli rutin menghasilkan keuntungan tanpa memandang kondisi pasar","Membuatmu bisa memprediksi harga besok dengan tepat, sehingga kamu tahu kapan harus membeli dan kapan harus menjual"],answer:0,explain:"Menyicil rutin meratakan harga beli & menjadikan investasi sebuah kebiasaan, bukan taruhan waktu. Tetap ada risiko pasar.",hint:"Dengan jumlah tetap, kamu dapat lebih banyak unit saat harga mahal atau murah?"},
{n:34,type:"mcq",micro:"Profil risiko",q:"'Profil risiko' seseorang dipengaruhi oleh...",options:["Usia dan jenis pekerjaan orang tuanya, karena investasi hanya cocok bagi anak dari keluarga berpenghasilan besar dan mapan di kota besar","Horizon waktu tujuan, kondisi keuangan (punya dana darurat & tak banyak utang), pengetahuan, serta seberapa nyaman ia menghadapi nilai yang turun","Zodiak, warna favorit, dan angka keberuntungan, karena nasib investasi ditentukan oleh hari lahir dan kebiasaan pemiliknya"],answer:1,explain:"Investasi yang cocok berbeda tiap orang. Kenali profil risikomu sebelum memilih, jangan meniru mentah-mentah pilihan orang lain.",hint:"Apa saja yang membuat dua orang cocok dengan investasi yang berbeda?"},
{n:35,type:"mcq",micro:"Menggeser ke aman saat mendekat",q:"Saat waktu pemakaian dana investasi jangka panjang makin dekat (mis. tinggal 1-2 tahun lagi), langkah bijak umumnya...",options:["Menambah risiko sebanyak mungkin untuk 'mengejar target', supaya dananya cepat bertambah sebelum waktu pemakaiannya tiba","Membiarkan semuanya tetap di aset yang paling berfluktuasi, karena memindahkannya ke tempat lain dianggap merugikan","Memindahkan sebagian ke instrumen lebih aman & likuid secara bertahap, agar tidak terkena penurunan besar tepat sebelum dipakai"],answer:2,explain:"Investasi berisiko butuh waktu untuk pulih dari penurunan. Mendekati tenggat, kepastian jumlah kembali menjadi prioritas.",hint:"Kalau uangnya dipakai tahun depan, beranikah ia turun 25% sekarang?"},
{n:36,type:"mcq",micro:"'Menabung' di instrumen berisiko",q:"Menaruh dana darurat di saham karena 'bunganya lebih besar' berisiko karena...",options:["Saat darurat terjadi bersamaan dengan pasar sedang turun, kamu terpaksa menjual rugi & dana yang tersedia lebih kecil dari yang dibutuhkan","Saham bisa dicairkan pada nilai tertingginya kapan pun diperlukan, sehingga kecil risikonya ketika dana darurat dibutuhkan mendadak","Dana darurat memang sebaiknya berisiko tinggi supaya cepat berkembang, sebab dana yang aman tidak bertambah sedikit pun"],answer:0,explain:"Fungsi dana darurat adalah kepastian & ketersediaan. Menukarnya demi imbal hasil membuatnya gagal justru saat paling dibutuhkan.",hint:"Bagaimana kalau ban mobil pecah di bulan yang sama saat pasar anjlok?"},
{n:37,type:"tf",micro:"Mulai kecil itu sah",q:"Benar atau Salah: Memulai menabung/berinvestasi dengan jumlah kecil itu sia-sia; selama setorannya belum besar, kebiasaan rutin tidak memberi dampak berarti.",answer:false,explain:"Sebaliknya, kebiasaan + waktu + bunga majemuk membuat setoran kecil yang konsisten tumbuh berarti. Menunggu 'punya banyak dulu' sering berarti tidak pernah mulai.",hint:"Konsistensi kecil selama bertahun-tahun, atau menunggu jumlah besar yang tak kunjung ada?"},
{n:38,type:"mcq",micro:"Utang berbunga tinggi vs investasi",q:"Punya utang kartu kredit berbunga sangat tinggi & sedikit uang lebih. Umumnya lebih menguntungkan...",options:["Menambah utang baru untuk modal investasi, karena keuntungan investasi dianggap menutup bunga utang kartu kredit dalam waktu singkat","Melunasi utang berbunga tinggi dulu — 'imbal hasil'-nya = bunga yang tidak jadi dibayar, sering lebih besar & lebih pasti daripada hasil investasi","Berinvestasi agresif sambil membiarkan utang berbunga tinggi berjalan, karena bunga utang dianggap lebih kecil dari untung investasi"],answer:1,explain:"Menghapus utang berbunga 24% ibarat 'keuntungan pasti 24%'. Sisakan dana darurat kecil, lalu prioritaskan melunasi utang mahal sebelum investasi.",hint:"Bunga utang yang kamu hindari vs perkiraan hasil investasi — mana lebih tinggi & lebih pasti?"},
{n:39,type:"mcq",micro:"Bukan nasihat personal",q:"Sikap yang tepat saat membaca informasi umum tentang investasi (termasuk pelajaran ini):",options:["Langsung membeli aset yang disebut dalam penjelasan itu, karena dianggap sudah cocok untuk semua pembacanya, termasuk yang belum paham risikonya","Menganggap semua jenis investasi cocok untuk setiap orang tanpa melihat tujuan, waktu, atau kemampuan menanggung risiko, sehingga tak perlu belajar lagi","Menganggapnya pengetahuan dasar untuk memahami pilihan, lalu belajar lebih lanjut & menyesuaikan dengan kondisi diri — bukan perintah membeli produk tertentu"],answer:2,explain:"Materi edukatif menjelaskan konsep & prinsip. Keputusan nyata perlu mempertimbangkan tujuan, kondisi, & profil risiko masing-masing.",hint:"Informasi umum untuk memahami, atau perintah membeli produk spesifik?"},
{n:40,type:"open",micro:"Menghitung dampak memulai lebih awal",q:"Dina menabung Rp200.000/bulan mulai umur 15 sampai 25 (10 tahun) lalu berhenti menyetor tetapi membiarkannya tumbuh. Riko baru mulai menabung Rp200.000/bulan dari umur 25 sampai 45 (20 tahun). Dengan pertumbuhan berbunga yang sama, jelaskan secara kualitatif siapa yang cenderung punya lebih banyak di umur 45 & mengapa.",explain:"Jawaban baik menyimpulkan bahwa Dina (mulai lebih awal) cenderung setara atau unggul meski menyetor lebih sedikit & lebih singkat, karena bunga majemuk memberi nilai terbesar pada uang yang punya waktu tumbuh paling lama, dan tahun-tahun awal tidak bisa digantikan.",hint:"Bandingkan bukan total setoran, tetapi berapa lama setiap rupiah pertama sempat 'berbunga atas bunga'.",sample:"Meskipun Riko menyetor dua kali lebih lama (20 tahun vs 10 tahun) dan total setorannya lebih besar, Dina sering kali berakhir dengan jumlah yang setara atau bahkan lebih besar di umur 45. Alasannya adalah waktu bekerja untuk bunga majemuk: uang Dina sudah mulai 'bertumbuh berbunga' 10 tahun lebih awal, dan selama 20 tahun setelah ia berhenti menyetor (umur 25-45) saldonya terus berbunga atas bunga. Setoran awal yang diberi waktu paling lama tumbuh paling besar. Riko kehilangan 10 tahun pertumbuhan paling berharga itu dan tidak bisa 'mengejarnya' hanya dengan menyetor lebih lama belakangan. Pelajarannya: memulai lebih awal, bahkan dengan jumlah kecil dan durasi pendek, sangat berpengaruh; menunda beberapa tahun berbiaya besar dalam jangka panjang."},
{n:41,type:"mcq",micro:"Alokasi sederhana",q:"Seseorang punya Rp10.000.000, belum punya dana darurat, tanpa utang. Langkah awal yang paling masuk akal:",options:["Sisihkan sebagian besar sebagai dana darurat di tabungan/deposito, baru sisanya dipertimbangkan untuk investasi jangka panjang secara bertahap","Menaruh seluruh Rp10.000.000 di satu saham yang sedang naik daun supaya cepat berlipat, lalu baru memikirkan dana darurat belakangan","Membelikan barang mewah supaya 'nilainya naik' kelak, karena barang mahal dianggap bisa dijual kembali dengan harga lebih tinggi"],answer:0,explain:"Amankan fondasi dulu (dana darurat), lalu investasikan uang yang benar-benar tidak dibutuhkan dalam waktu dekat.",hint:"Apa yang harus ada sebelum uang 'dikunci' untuk tumbuh?"},
{n:42,type:"mcq",micro:"Tujuan 6 bulan",q:"Menabung untuk laptop yang akan dibeli 6 bulan lagi. Tempat paling tepat:",options:["Investasi kripto yang berfluktuasi tinggi, karena harganya bisa naik cepat sehingga laptop terbeli lebih awal","Tabungan biasa atau deposito jangka pendek — aman & jumlahnya pasti saat dibutuhkan","Saham perusahaan teknologi agar 'sekalian untung', sebab harganya diperkirakan naik"],answer:1,explain:"6 bulan terlalu pendek untuk menanggung risiko penurunan. Prioritas: uangnya utuh & siap saat waktunya.",hint:"Beranikah kamu jumlah untuk laptop itu turun 20% di bulan ke-5?"},
{n:43,type:"mcq",micro:"Tujuan 15 tahun",q:"Menyiapkan dana pendidikan anak untuk 15 tahun lagi. Pendekatan umum yang masuk akal:",options:["Seluruhnya disimpan tunai di rumah selama 15 tahun tanpa disentuh, sebab uang tunai dianggap tidak berisiko dan nilainya tetap terjaga","Dihabiskan sekarang untuk keperluan lain, lalu nanti mencari pinjaman ketika biaya pendidikan sudah dibutuhkan, tanpa persiapan sebelumnya","Sebagian diinvestasikan pada aset pertumbuhan yang terdiversifikasi & disetor rutin, lalu digeser bertahap ke aset lebih aman saat mendekati tahun pemakaian"],answer:2,explain:"Horizon panjang cocok untuk pertumbuhan; menabung rutin membangun disiplin; menggeser ke aman di akhir melindungi hasil.",hint:"15 tahun memberi ruang untuk tumbuh — lalu apa yang dilakukan menjelang tahun ke-14?"},
{n:44,type:"mcq",micro:"Menghadapi pasar turun",q:"Investasi jangka panjangmu (untuk 12 tahun lagi) turun 20% karena pasar sedang lesu. Tindakan yang umumnya bijak:",options:["Tetap pada rencana, lanjutkan setoran rutin bila mampu, & tidak menjual panik — karena horizonnya masih panjang","Jual semuanya sekarang untuk 'menyelamatkan sisa', karena penurunan 20% dianggap akan berlanjut sampai nilainya nol","Pindahkan seluruhnya ke satu aset yang 'katanya' akan meroket, supaya kerugian cepat tertutup tanpa menunggu pasar pulih"],answer:0,explain:"Penurunan hanya menjadi kerugian nyata bila kamu menjual. Pada horizon panjang, pasar punya waktu untuk pulih; setoran saat harga rendah bahkan membeli lebih banyak unit.",hint:"Kapan 'turun di layar' berubah jadi 'rugi sungguhan'?"},
{n:45,type:"order",micro:"Merancang tujuan menabung/investasi",q:"Urutkan langkah menyiapkan sebuah tujuan keuangan.",items:["Tentukan tujuan, jumlah yang dibutuhkan, & kapan (horizon waktu)","Pilih wadah: tabungan/deposito untuk horizon pendek, investasi terdiversifikasi untuk horizon panjang","Tetapkan setoran rutin yang realistis & otomatiskan bila bisa","Tinjau berkala; geser ke aset lebih aman saat tujuan makin dekat"],answer:[0,1,2,3],explain:"Tujuan & waktu → pilih wadah sesuai horizon → setor rutin → tinjau & amankan menjelang tenggat.",hint:"Apa yang harus jelas sebelum memilih tabungan atau investasi?"},
{n:46,type:"mcq",micro:"Menolak ajakan teman",q:"Teman mengajak 'ikut investasi' yang menjanjikan untung 10%/minggu & bonus kalau mengajak orang lain. Sikap tepat:",options:["Pinjam uang tambahan agar untung yang didapat lebih besar, karena imbal hasil sebesar itu dianggap menutup bunga pinjamannya","Menolak & memperingatkan teman: imbal hasil sebesar itu + fokus merekrut adalah ciri kuat skema penipuan yang akan merugikan mayoritas peserta","Ikut dengan uang sedikit dulu 'untuk coba-coba', lalu tambah setoran dan ajak teman lain kalau pembayaran pertamanya lancar"],answer:1,explain:"'Coba sedikit' pada skema penipuan tetap menormalkan & menyebarkannya. Prinsip risiko-imbal hasil dilanggar terang-terangan di sini.",hint:"10% per minggu 'pasti' + bonus rekrut — logis atau tanda bahaya?"},
{n:47,type:"mcq",micro:"Menghitung kebutuhan setoran",q:"Butuh Rp24.000.000 untuk 4 tahun lagi. Bila diasumsikan hanya ditabung tanpa pertumbuhan berarti, setoran per bulan kira-kira...",options:["Rp24.000.000 ÷ 4 = Rp6.000.000/bulan","Rp2.000.000/bulan","Rp24.000.000 ÷ 48 bulan = Rp500.000/bulan"],answer:2,explain:"4 tahun = 48 bulan. Rp24.000.000 ÷ 48 = Rp500.000. Pertumbuhan (bila ada) bisa sedikit meringankan, tetapi untuk horizon pendek jangan mengandalkannya.",hint:"Ubah 4 tahun ke bulan, lalu bagi."},
{n:48,type:"mcq",micro:"Terlalu banyak di satu aset",q:"Seluruh tabungan keluarga ditaruh di saham satu perusahaan tempat ayah bekerja. Risiko utamanya:",options:["Bila perusahaan itu bermasalah, keluarga bisa kehilangan pekerjaan & tabungan sekaligus — risiko yang menumpuk di satu titik","Risiko kecil karena ayah mengenal perusahaan itu dengan baik dan tahu betul bagaimana keadaan di dalamnya","Untung karena ayah 'tahu dari dalam', sehingga tabungan keluarga lebih aman dibanding diinvestasikan di tempat lain"],answer:0,explain:"Diversifikasi juga berarti tidak menautkan seluruh nasib keuangan pada satu perusahaan/industri, apalagi yang sudah jadi sumber penghasilan.",hint:"Kalau perusahaan itu jatuh, berapa banyak hal yang hilang sekaligus?"},
{n:49,type:"mcq",micro:"Membandingkan dua produk",q:"Dua reksadana sejenis: X biaya 1%/tahun, Y biaya 3%/tahun, kinerja historis mirip. Dalam jangka panjang...",options:["Biaya tidak berpengaruh pada hasil akhir dalam jangka panjang, sehingga memilih yang murah atau mahal memberi hasil setara","X cenderung memberi hasil bersih lebih baik karena biaya yang lebih rendah tidak menggerus hasil sebanyak Y","Y lebih baik karena biayanya yang lebih tinggi berarti dikelola lebih berkualitas, sehingga hasil bersihnya lebih besar dari X"],answer:1,explain:"Biaya adalah salah satu hal yang paling bisa kamu kendalikan. Selisih 2%/tahun terkompaun menjadi perbedaan besar dalam belasan tahun.",hint:"Biaya lebih rendah memakan hasil lebih sedikit atau lebih banyak?"},
{n:50,type:"open",micro:"Menyusun rencana untuk seseorang",q:"Bu Sari, 30 tahun, penghasilan stabil, punya utang kartu kredit Rp5.000.000 (bunga tinggi), belum ada dana darurat, ingin mulai 'berinvestasi untuk masa depan'. Susun urutan langkah yang kamu sarankan (4-5 langkah) beserta alasan, tanpa menyebut produk spesifik.",explain:"Jawaban baik mengurutkan: anggaran surplus → lunasi utang berbunga tinggi (dengan penyangga kecil) → dana darurat 3-6 bulan → baru investasi rutin terdiversifikasi sesuai profil risiko → tinjau berkala; masing-masing dengan alasan, tanpa merekomendasikan produk tertentu.",hint:"Fondasi dulu (anggaran, utang mahal, dana darurat), pertumbuhan kemudian; jangan menyebut produk spesifik.",sample:"Langkah 1: Buat anggaran agar pengeluaran jelas lebih kecil dari penghasilan, dan tentukan berapa yang bisa disisihkan tiap bulan. Alasan: tanpa surplus, tidak ada uang untuk langkah berikutnya. Langkah 2: Lunasi utang kartu kredit berbunga tinggi lebih dulu (sambil menyimpan dana darurat kecil, misalnya Rp2-3 juta, sebagai penyangga). Alasan: bunga kartu kredit biasanya jauh lebih tinggi daripada imbal hasil investasi yang realistis, jadi melunasinya memberi 'keuntungan pasti'. Langkah 3: Bangun dana darurat sekitar 3-6 bulan biaya hidup di tempat yang aman dan mudah diambil. Alasan: mencegah harus berutang lagi atau menjual investasi saat ada kejutan. Langkah 4: Setelah fondasi aman, mulai investasi rutin dengan jumlah yang realistis untuk tujuan jangka panjang, pilih yang terdiversifikasi sesuai profil risikonya, dan otomatiskan setorannya. Alasan: konsistensi + waktu + diversifikasi adalah inti investasi yang sehat. Langkah 5: Tinjau berkala, tambah setoran saat penghasilan naik, dan pelajari lebih lanjut sebelum menambah jenis investasi. Alasan: rencana perlu disesuaikan seiring waktu."},
{n:51,type:"mcq",micro:"Ekspektasi realistis",q:"Ekspektasi imbal hasil jangka panjang yang lebih realistis untuk investasi terdiversifikasi adalah...",options:["Untung besar yang sama setiap bulan tanpa rugi, karena investasi yang baik dianggap stabil dan terjamin hasilnya","Nol, sebab investasi tidak tumbuh dalam jangka panjang sehingga uang lebih baik disimpan saja tanpa dikembangkan","Angka moderat yang berfluktuasi tahun ke tahun (kadang untung, kadang rugi), bukan angka besar yang tetap & dijamin setiap bulan"],answer:2,explain:"Imbal hasil nyata datang bergelombang: beberapa tahun positif, sebagian negatif, dengan rata-rata jangka panjang yang moderat. Janji 'tetap & tinggi' tidak realistis.",hint:"Bergelombang dengan rata-rata moderat, atau mulus dan tinggi selamanya?"},
{n:52,type:"tf",micro:"Menjual saat panik",q:"Benar atau Salah: Menjual seluruh investasi jangka panjang karena panik saat harga turun tajam sering mengubah penurunan sementara menjadi kerugian yang permanen.",answer:true,explain:"Selama belum dijual, penurunan hanyalah angka yang bisa pulih. Menjual di titik rendah mengunci kerugian & sering membuat orang ketinggalan pemulihan berikutnya.",hint:"Kapan 'turun di layar' menjadi 'uang benar-benar hilang'?"},
{n:53,type:"mcq",micro:"'Orang dalam' & bisikan",q:"Seseorang memberi 'tips rahasia' saham yang 'pasti naik minggu depan'. Sikap tepat:",options:["Sangat skeptis: tidak ada yang memastikan harga jangka pendek; 'tips pasti' sering menyesatkan atau upaya menggerakkan harga demi untung si pembisik","Segera memakai seluruh tabungan untuk membelinya, karena kesempatan itu harus diambil sebelum orang lain mendahului, apalagi dari tokoh terkenal","Mengajak banyak teman ikut membeli supaya harganya cepat naik, sebab makin banyak pembeli dianggap makin besar untung yang didapat semua pihak"],answer:0,explain:"Keputusan investasi yang sehat berdasarkan tujuan & diversifikasi, bukan bisikan jangka pendek yang tak bisa diverifikasi.",hint:"Bisakah seseorang benar-benar tahu harga minggu depan dengan pasti?"},
{n:54,type:"mcq",micro:"Menambah setoran saat penghasilan naik",q:"Ketika penghasilan naik, kebiasaan yang memperkuat keuangan jangka panjang:",options:["Berhenti menabung dan berinvestasi karena penghasilan sudah naik dan merasa kebutuhan masa depan sudah cukup terpenuhi","Menaikkan porsi yang ditabung/diinvestasikan, bukan hanya menaikkan gaya hidup sebesar kenaikan itu","Menghabiskan seluruh kenaikan itu untuk barang-barang baru, karena kenaikan penghasilan memang pantas dinikmati sepenuhnya"],answer:1,explain:"Menghindari 'inflasi gaya hidup' (pengeluaran selalu mengejar penghasilan) adalah cara ampuh mempercepat tujuan keuangan.",hint:"Kenaikan gaji sebaiknya sebagian besar menambah tabungan/investasi, atau menambah pengeluaran?"},
{n:55,type:"mcq",micro:"Menghitung dana darurat",q:"Biaya hidup keluarga Rp5.000.000/bulan. Target dana darurat 6 bulan berarti...",options:["Rp5.000.000 sekali saja, karena dana darurat cukup untuk satu bulan","Rp60.000.000 ditaruh di saham agar cepat berkembang, sebab dana darurat sebaiknya dikembangkan","Rp30.000.000 disimpan di tempat aman & likuid, dikumpulkan bertahap"],answer:2,explain:"6 × Rp5.000.000 = Rp30.000.000. Dikumpulkan sedikit demi sedikit; ditaruh di tabungan/deposito, bukan aset berisiko.",hint:"Kalikan biaya bulanan dengan jumlah bulan target."},
{n:56,type:"tf",micro:"Investasi butuh belajar",q:"Benar atau Salah: Kamu tidak perlu memahami cara kerja, risiko, biaya, atau cara mencairkan sebuah investasi sebelum menaruh uang di sana — yang penting hasilnya.",answer:false,explain:"Sebaliknya, 'jangan berinvestasi pada yang tidak kamu pahami.' Memahami cara kerja, risiko, biaya, & likuiditasnya melindungimu dari produk yang tidak cocok & dari penipuan.",hint:"Menaruh uang dulu lalu belajar, atau belajar dulu baru menaruh uang?"},
{n:57,type:"mcq",micro:"Kapan menabung 'kalah' dari inflasi",q:"Bila bunga tabungan 2%/tahun sementara inflasi 4%/tahun, maka daya beli uang di tabungan itu...",options:["Sedikit menurun tiap tahun, karena kenaikan harga lebih cepat daripada pertumbuhan tabungan","Naik 2% setiap tahun, karena bunga tabungan lebih besar daripada kenaikan harga","Tetap sama setiap tahun, karena bunga tabungan tepat menutup kenaikan harga barang"],answer:0,explain:"Tabungan tetap penting untuk keamanan & dana darurat, tetapi untuk tujuan jangka sangat panjang, mengandalkan tabungan saja bisa kalah oleh inflasi.",hint:"Bandingkan 2% pertumbuhan dengan 4% kenaikan harga."},
{n:58,type:"mcq",micro:"Rebalancing (gagasan)",q:"Setelah beberapa tahun, komposisi investasi bergeser (mis. bagian saham membesar karena naik). 'Menyeimbangkan ulang' berarti...",options:["Membiarkan komposisi berjalan sendiri tanpa ditinjau, supaya porsi aset yang tumbuh makin besar walau risikonya ikut naik jauh dari rencana","Menyesuaikan kembali ke komposisi rencana semula (mis. menjual sebagian yang membesar, menambah yang mengecil) agar tingkat risiko tetap sesuai tujuan","Menjual semuanya lalu membeli ulang di waktu yang dianggap paling tepat, supaya komposisinya kembali ke bentuk semula dalam sekejap"],answer:1,explain:"Rebalancing menjaga portofolio tidak diam-diam menjadi jauh lebih berisiko (atau terlalu konservatif) dibanding rencana.",hint:"Mengembalikan proporsi ke rencana awal, atau membiarkannya menyimpang terus?"},
{n:59,type:"mcq",micro:"Menilai 'sudah untung, jual?'",q:"Investasi jangka panjangmu naik 25% dalam setahun. Godaan menjual semua untuk 'mengamankan untung' sebaiknya ditimbang dengan...",options:["Menjual begitu untungnya mencapai 25%, tanpa melihat tujuan dan rencana jangka panjang, karena untung yang tidak dicairkan bisa hilang begitu saja","Menahan terus meski kondisi berubah, tanpa mengevaluasi tujuan atau kondisi keuangan, karena menjual dianggap kesalahan yang merugikan investor jangka panjang","Apakah tujuan sudah dekat? Apakah rencana jangka panjang berubah? Menjual hanya karena naik bisa membuatmu ketinggalan pertumbuhan & bingung kapan masuk lagi"],answer:2,explain:"Keputusan jual sebaiknya terkait tujuan & rencana, bukan sekadar reaksi terhadap angka naik atau turun.",hint:"Jual karena tujuan tercapai, atau jual hanya karena grafiknya hijau?"},
{n:60,type:"open",micro:"Membandingkan tiga pilihan penempatan",q:"Kamu punya Rp12.000.000 yang tidak akan dipakai minimal 10 tahun, dana darurat sudah ada, tidak punya utang. Tiga pilihan: (A) seluruhnya di tabungan biasa bunga ~2%, (B) seluruhnya di satu saham yang 'kata orang bagus', (C) dibagi ke beberapa jenis aset terdiversifikasi & disetori rutin. Bahas kelebihan-kekurangan tiap opsi & mana yang paling masuk akal.",explain:"Jawaban baik menilai A terlalu konservatif (kalah inflasi untuk horizon 10 tahun), B terlalu terkonsentrasi/berisiko dan berdasar rumor, dan memilih C (diversifikasi + setor rutin) sebagai paling masuk akal mengingat horizon panjang, dana darurat ada, tanpa utang — sambil menyebut kaveat profil risiko, biaya, dan menggeser ke aman menjelang tenggat.",hint:"Nilai tiap opsi terhadap horizon 10 tahun, inflasi, konsentrasi risiko, dan diversifikasi; ingat fondasinya sudah aman.",sample:"(A) Tabungan biasa: sangat aman dan likuid, tetapi bunga ~2% kemungkinan besar kalah oleh inflasi dalam 10 tahun, sehingga daya beli Rp12.000.000 justru menurun. Untuk uang yang sengaja tidak dipakai 10 tahun, ini terlalu konservatif. (B) Satu saham: potensi tumbuh besar, tetapi risiko sangat terkonsentrasi — bila perusahaan itu bermasalah, sebagian besar atau seluruh dana bisa hilang, dan 'kata orang bagus' bukan dasar yang kuat. (C) Terdiversifikasi + setor rutin: potensi pertumbuhan jangka panjang di atas inflasi, risiko tersebar sehingga satu aset yang jatuh tidak menghancurkan semuanya, dan setoran rutin membangun kebiasaan serta meratakan harga beli. Kekurangannya: nilai tetap berfluktuasi jangka pendek dan ada biaya pengelolaan yang harus dibandingkan. Paling masuk akal: opsi C, karena horizon 10 tahun, dana darurat sudah ada, dan tidak ada utang — kondisi yang cocok untuk pertumbuhan terdiversifikasi. Tetap perlu menyesuaikan jenis aset dengan profil risiko pribadi, memahami produknya, dan menggeser ke lebih aman saat mendekati tahun ke-9 atau ke-10."},
{n:61,type:"mcq",micro:"Mengapa investasi memberi imbal hasil lebih tinggi",q:"Alasan mendasar investasi berpotensi memberi imbal hasil lebih tinggi daripada menabung:",options:["Kamu mengambil risiko (nilai bisa turun) & menyediakan modal bagi kegiatan ekonomi; imbal hasil adalah kompensasi atas risiko & kesabaran itu","Karena bank memberi hadiah tambahan kepada nasabah yang berinvestasi, sehingga hasilnya otomatis lebih besar daripada menabung biasa","Karena investasi tidak punya risiko, sedangkan tabungan punya risiko, sehingga investasi memberi hasil lebih tinggi daripada tabungan"],answer:0,explain:"Tidak ada imbal hasil ekstra tanpa risiko ekstra. Menabung membayar sedikit karena hampir tanpa risiko & sangat likuid.",hint:"Apa yang kamu 'berikan' saat berinvestasi yang tidak kamu berikan saat menabung?"},
{n:62,type:"mcq",micro:"Mengapa horizon panjang meredam risiko",q:"Mengapa risiko investasi terasa lebih kecil pada horizon panjang?",options:["Karena pemerintah menjamin investasi jangka panjang sehingga uang pokok kembali penuh pada akhir periode yang panjang itu","Semakin lama waktunya, semakin besar peluang pasar pulih dari penurunan & pertumbuhan rata-rata mendekati kecenderungan jangka panjangnya","Karena harga bergerak semakin tenang dalam jangka panjang, sehingga naik turunnya nilai tidak terjadi lagi di masa depan"],answer:1,explain:"Fluktuasi tahunan besar, tetapi rata-rata belasan tahun cenderung lebih stabil. Itulah mengapa uang jangka pendek tidak cocok diinvestasikan.",hint:"Penurunan butuh apa untuk pulih, dan horizon panjang memberi apa?"},
{n:63,type:"tf",micro:"Menabung tetap penting",q:"Benar atau Salah: Karena investasi berpotensi tumbuh lebih besar, sebaiknya seluruh uang — termasuk dana darurat — diinvestasikan & tidak perlu ada tabungan.",answer:false,explain:"Sebaliknya, dana darurat & uang untuk kebutuhan dekat harus tetap ditabung di tempat aman & likuid. Tanpa itu, kamu terpaksa menjual investasi saat rugi ketika keadaan darurat datang.",hint:"Apa yang terjadi bila darurat datang bersamaan dengan pasar turun & semua uangmu di investasi?"},
{n:64,type:"mcq",micro:"Menilai janji 'dijamin'",q:"Mengapa 'investasi dengan imbal hasil tinggi yang dijamin' hampir pasti bermasalah?",options:["Karena imbal hasil tinggi bisa dijamin oleh lembaga yang bereputasi baik dan punya kantor megah, sehingga tidak ada hal yang perlu dicurigai di dalamnya","Karena pemerintah melarang investasi dengan imbal hasil tinggi, sehingga semuanya ilegal dan harus ditutup segera setelah ditemukan oleh petugas","Imbal hasil tinggi selalu datang dengan ketidakpastian; 'menjamin' yang tinggi berarti menyembunyikan risiko, memakai uang anggota baru (Ponzi), atau berbohong"],answer:2,explain:"Prinsip risiko-imbal hasil tidak bisa dilanggar. 'Tinggi + dijamin + tanpa risiko' adalah kombinasi kata yang menandai penipuan.",hint:"Bisakah sesuatu benar-benar memberi untung besar sekaligus benar-benar pasti?"},
{n:65,type:"mcq",micro:"Biaya kecil, dampak besar",q:"Mengapa biaya 2% per tahun bisa sangat berpengaruh pada hasil investasi 20 tahun?",options:["Karena biaya dipotong setiap tahun dari seluruh nilai, & 'kehilangan pertumbuhan atas bagian yang terpotong' ikut terkompaun sepanjang waktu","Karena biaya hanya dibayar sekali di awal investasi, sehingga pengaruhnya langsung hilang dan tidak berlanjut pada tahun berikutnya","Karena biaya tidak berpengaruh pada hasil akhir, sebab yang menentukan hanyalah besar kecilnya setoran awal yang kamu tanam"],answer:0,explain:"Sama seperti bunga majemuk menumbuhkan uangmu, biaya majemuk menggerogotinya. Membandingkan biaya adalah keputusan berdampak besar yang sering diabaikan.",hint:"Kalau 2% hilang tiap tahun, apa juga yang hilang selain 2% itu?"},
{n:66,type:"mcq",micro:"Membandingkan 'menabung 100%' vs 'investasi 100%' untuk tujuan 20 tahun",q:"Untuk tujuan 20 tahun, kelemahan utama menaruh 100% di tabungan berbunga sangat rendah:",options:["Tabungan tidak bisa diambil selama 20 tahun, sehingga uangnya terkunci dan tidak bisa dipakai bila ada keperluan","Pertumbuhannya kemungkinan tidak mengimbangi inflasi, sehingga daya beli dana berkurang meski angkanya bertambah sedikit","Tabungan terlalu berisiko untuk 20 tahun karena nilainya bisa turun tajam tiap tahun, melebihi risiko saham"],answer:1,explain:"Untuk horizon sangat panjang, risiko 'terlalu aman' adalah nyata: kehilangan daya beli. Keseimbangan tabungan-investasi bergantung tujuan & waktu.",hint:"Apa yang terjadi pada Rp1 juta di tabungan 2% selama 20 tahun inflasi 4%?"},
{n:67,type:"tf",micro:"Menebak waktu pasar itu sulit",q:"Benar atau Salah: Bahkan para profesional pun sulit menebak secara konsisten kapan pasar akan naik atau turun, sehingga menyicil rutin & bertahan jangka panjang umumnya lebih andal daripada mencoba 'masuk-keluar' di waktu yang tepat.",answer:true,explain:"Mencoba mengatur waktu pasar berisiko ketinggalan hari-hari kenaikan terbesar. Konsistensi & kesabaran adalah strategi yang lebih bisa dijalankan orang biasa.",hint:"Bisakah seseorang menebak titik naik-turun secara konsisten selama bertahun-tahun?"},
{n:68,type:"mcq",micro:"Mengapa diversifikasi masuk akal",q:"Diversifikasi masuk akal karena...",options:["Kamu bisa memastikan semua aset akan naik bersamaan, sehingga menyebar uang membuat semua bagiannya menguntungkan sekaligus sepanjang waktu","Satu aset terbaik bisa diketahui sebelumnya dengan yakin, jadi menaruh seluruh uang di sana adalah pilihan paling masuk akal","Kamu tidak tahu pasti aset mana yang akan berkinerja terbaik/terburuk; menyebar membuat hasil lebih stabil & mengurangi dampak kesalahan tunggal"],answer:2,explain:"Diversifikasi adalah pengakuan jujur atas ketidakpastian. Ia menukar 'peluang menang besar dari satu tebakan' dengan 'hasil lebih andal'.",hint:"Kalau kamu tahu pasti pemenangnya, perlukah menyebar? Apakah kamu benar-benar tahu?"},
{n:69,type:"mcq",micro:"Menilai testimoni",q:"Iklan investasi menampilkan orang-orang yang 'sukses jadi kaya'. Ini bukan bukti kuat karena...",options:["Testimoni dipilih & bisa dibayar/dibuat; kamu tidak melihat mayoritas yang rugi, & hasil masa lalu tidak menjamin masa depan","Testimoni di iklan akurat dan mewakili semua peserta, sehingga kisah sukses yang ditampilkan dialami oleh kebanyakan orang","Orang jarang berbohong soal uang, jadi kisah kekayaan yang mereka ceritakan benar adanya dan bisa kamu tiru dengan mudah"],answer:0,explain:"'Bias bertahan hidup': yang gagal tidak tampil. Nilai sebuah investasi dari cara kerjanya & legalitasnya, bukan dari kisah sukses pilihan.",hint:"Apakah kamu melihat orang-orang yang rugi di iklan itu?"},
{n:70,type:"order",micro:"Berpikir saat tergiur imbal hasil tinggi",q:"Urutkan proses berpikir sehat saat mendengar peluang 'imbal hasil sangat tinggi'.",items:["Tenangkan diri & tolak tekanan untuk memutuskan cepat","Tanya: dari mana keuntungannya berasal, & apakah masuk akal tanpa merekrut orang?","Cek legalitas & izin di otoritas berwenang","Bila tidak jelas atau melanggar prinsip risiko-imbal hasil, lewati & lindungi modalmu"],answer:[0,1,2,3],explain:"Redakan tekanan → uji logika keuntungan → cek legalitas → putuskan konservatif. Modal yang terjaga bisa berkembang; modal yang hilang tidak.",hint:"Langkah pertama melawan buru-buru; langkah terakhir mengambil sikap aman."},
{n:71,type:"mcq",micro:"Menabung sebagai 'penampung' investasi",q:"Peran tabungan bagi seorang investor jangka panjang:",options:["Menggantikan fungsi investasi, sehingga investor jangka panjang tidak memerlukan aset lain selain rekening tabungan biasa","Menjadi dana darurat & tempat parkir uang untuk kebutuhan dekat, sehingga investasi tidak perlu dijual di saat yang buruk","Tidak berperan bagi investor jangka panjang, karena uang sebaiknya langsung ditanamkan tanpa menyisakan simpanan"],answer:1,explain:"Tabungan & investasi saling mendukung: tabungan yang kuat justru membuat kamu bisa membiarkan investasi bekerja tanpa gangguan.",hint:"Apa yang melindungi investasimu dari 'terpaksa dijual saat rugi'?"},
{n:72,type:"mcq",micro:"Menghitung 'aturan 72' (gagasan)",q:"'Aturan 72' memperkirakan lama waktu uang berlipat ganda dengan membagi 72 dengan persen pertumbuhan tahunan. Pada 8%/tahun, uang berlipat ganda sekitar...",options:["72 × 8 = 576 tahun","8 ÷ 72 tahun","72 ÷ 8 = 9 tahun"],answer:2,explain:"Aturan praktis ini menunjukkan betapa besarnya pengaruh tingkat pertumbuhan & waktu. Pada 8%, ~9 tahun; pada 4%, ~18 tahun.",hint:"Bagi 72 dengan angka pertumbuhannya."},
{n:73,type:"tf",micro:"Semua utang harus lunas sebelum investasi?",q:"Benar atau Salah: Semua jenis utang, termasuk yang berbunga sangat rendah, wajib dilunasi total sebelum boleh menyisihkan sepeser pun untuk investasi.",answer:false,explain:"Sebaliknya, yang perlu diprioritaskan adalah utang berbunga tinggi. Untuk utang berbunga rendah jangka panjang, banyak orang menjalankannya bersamaan dengan menabung/berinvestasi, asalkan anggaran sehat & ada dana darurat.",hint:"Apakah utang berbunga 3% dan utang berbunga 30% harus diperlakukan sama persis?"},
{n:74,type:"mcq",micro:"Mengapa 'mulai awal' begitu kuat",q:"Alasan memulai menabung/berinvestasi lebih awal begitu berpengaruh:",options:["Setoran paling awal punya waktu paling lama untuk 'berbunga atas bunga', & tahun-tahun pertumbuhan di awal tidak bisa digantikan dengan menyetor lebih banyak di kemudian hari","Karena uang yang lama disimpan bertambah dengan sendirinya tanpa sebab, sehingga cukup menunggu waktu tanpa perlu menyetor secara rutin dan hasilnya sudah menyusul","Karena memulai belakangan lebih untung, sebab harga aset biasanya lebih murah di masa depan dibanding sekarang, sehingga setoran awal tidak terlalu penting"],answer:0,explain:"Waktu adalah faktor yang paling tidak bisa dibeli kembali. Bahkan jumlah kecil yang mulai lebih dulu memberi keunggulan besar.",hint:"Rupiah mana yang tumbuh paling besar: yang punya 30 tahun atau 10 tahun untuk berbunga?"},
{n:75,type:"mcq",micro:"Menilai 'investasi' yang tak bisa dijelaskan",q:"Bila penjual sebuah 'investasi' tidak bisa menjelaskan dengan jelas ke mana uangmu diputar & bagaimana keuntungan dihasilkan, sikap tepat:",options:["Menaruh uang yang banyak sekalian agar tidak rugi kesempatan, sebab penjelasan rinci kurang penting untuk diketahui","Jangan menaruh uang — ketidakjelasan sumber keuntungan adalah tanda bahaya besar (bisa Ponzi atau penipuan)","Percaya saja karena mungkin 'terlalu rumit untuk dijelaskan' kepada orang awam, dan penjualnya lebih paham darimu"],answer:1,explain:"Investasi sah bisa menjelaskan model keuntungannya. 'Rahasia' atau 'terlalu canggih untuk dipahami' sering menyembunyikan bahwa tidak ada usaha nyata.",hint:"Kalau tidak ada yang bisa menjelaskan dari mana untungnya, dari mana untungnya?"},
{n:76,type:"mcq",micro:"Tabungan vs deposito vs investasi",q:"Diurutkan dari umumnya paling likuid ke paling tidak likuid (paling mudah diambil ke paling sulit dicairkan cepat tanpa rugi):",options:["Investasi jangka panjang → tabungan → deposito","Deposito → tabungan → investasi","Tabungan → deposito → sebagian investasi jangka panjang"],answer:2,explain:"Tabungan bisa diambil kapan saja; deposito 'terkunci' hingga jatuh tempo; sebagian investasi butuh waktu/biaya & nilainya bisa sedang turun saat kamu perlu menjual.",hint:"Mana yang bisa kamu tarik hari ini juga tanpa penalti?"},
{n:77,type:"tf",micro:"Risiko juga soal 'terlalu aman'",q:"Benar atau Salah: Untuk tujuan berjangka sangat panjang, hanya mengandalkan tempat 'paling aman' berbunga rendah juga mengandung risiko, yaitu kehilangan daya beli akibat inflasi.",answer:true,explain:"Risiko bukan hanya 'nilai turun', tetapi juga 'nilai tidak tumbuh cukup untuk mengejar harga'. Keseimbangan yang tepat bergantung pada tujuan & horizon.",hint:"Kalau uang tumbuh 2% tapi harga naik 4% selama 25 tahun, apa yang terjadi?"},
{n:78,type:"mcq",micro:"Menyesuaikan, bukan meniru",q:"Mengapa meniru mentah-mentah komposisi investasi orang lain bisa keliru?",options:["Tujuan, horizon waktu, kondisi keuangan, & toleransi risiko tiap orang berbeda; yang cocok untuk satu orang bisa terlalu berisiko atau terlalu konservatif bagi yang lain","Karena setiap orang seharusnya berinvestasi dengan komposisi yang persis sama, sehingga satu orang yang berhasil bisa jadi patokan bagi yang lain pada setiap saat","Karena meniru memberi hasil yang identik dengan orang yang ditiru, sehingga risikonya tidak berbeda bagi orang lain yang meniru, walau tujuannya tidak sama"],answer:0,explain:"Keputusan yang baik dimulai dari situasimu sendiri. Informasi orang lain berguna sebagai pembelajaran, bukan cetakan.",hint:"Apakah kebutuhan & keadaan keuanganmu sama persis dengan orang lain?"},
{n:79,type:"mcq",micro:"Menimbang menjual investasi untuk kebutuhan",q:"Kamu perlu dana mendesak & hanya punya investasi jangka panjang yang sedang turun 20%. Pelajaran ke depan:",options:["Seharusnya semua uang ditaruh di investasi berisiko sejak awal tanpa penyangga, supaya keuntungannya lebih besar dan tidak perlu menyimpan tabungan","Ini persis situasi yang dicegah oleh dana darurat; ke depan, prioritaskan membangun tabungan penyangga agar investasi tak perlu dijual di saat buruk","Investasi jangka panjang memang dibuat untuk dijual kapan pun dibutuhkan, jadi penurunan 20% itu tidak masalah dan tidak perlu dihindari"],answer:1,explain:"Terpaksa menjual di titik rugi adalah kerugian nyata. Dana darurat memutus rantai 'darurat → jual rugi'.",hint:"Apa yang seharusnya ada agar kamu tidak perlu menyentuh investasi saat darurat?"},
{n:80,type:"open",micro:"Menjelaskan menabung vs investasi ke adik",q:"Adikmu bertanya, 'Kalau investasi bisa lebih untung, kenapa orang masih menabung? Kenapa nggak semua uang diinvestasikan saja?' Jawab dengan bahasa sederhana, sertakan minimal 3 alasan.",explain:"Jawaban baik menjelaskan bahwa keduanya melayani tujuan berbeda dan memberi minimal 3 alasan menabung tetap perlu: kebutuhan jangka pendek butuh kepastian jumlah, dana darurat butuh likuiditas, dan investasi membawa risiko yang tidak cocok untuk semua uang/orang; ditutup dengan urutan tabung dulu lalu investasikan uang jangka panjang.",hint:"Pikirkan: kapan uang dipakai, apa yang terjadi saat darurat, dan mengapa risiko investasi tidak cocok untuk semua uang.",sample:"Menabung dan investasi itu dua alat untuk dua pekerjaan berbeda, jadi kebanyakan orang butuh keduanya. Pertama, soal waktu: uang yang akan dipakai dalam waktu dekat (bayar sekolah, beli barang tahun ini, dana darurat) harus aman dan pasti jumlahnya. Investasi bisa turun nilainya kapan saja, jadi bahaya kalau uang itu dipakai sebentar lagi. Kedua, soal dana darurat: kalau tiba-tiba ada yang sakit atau motor rusak, kita butuh uang yang bisa diambil hari itu juga. Kalau semua uang diinvestasikan dan pasar sedang turun, kita terpaksa menjual rugi atau malah berutang. Ketiga, soal ketenangan dan risiko: investasi memberi peluang tumbuh justru karena ada risiko rugi; tidak semua orang, dan tidak semua tujuan, cocok menanggung risiko itu. Jadi caranya: tabung dulu untuk keamanan dan kebutuhan dekat plus dana darurat, lalu investasikan uang yang memang tidak dipakai bertahun-tahun supaya tumbuh melawan inflasi."},
{n:81,type:"mcq",micro:"Kasus: 'trading' cepat dari influencer",q:"Seorang pemengaruh mengajak ikut 'kelas trading' berbayar yang menjanjikan 'cuan konsisten tiap hari' & memamerkan mobil mewah. Sikap tepat:",options:["Segera daftar sebelum kuotanya habis, karena keuntungan konsisten tiap hari menunjukkan kelas itu terbukti berhasil dan bermanfaat, apalagi pengikutnya banyak dan pamer hasilnya","Pinjam uang untuk modal trading dalam jumlah besar agar bisa meniru gaya hidup mewahnya, karena dia terbukti sukses, lalu mengajak teman ikut kelasnya","Sangat skeptis: keuntungan harian yang konsisten tidak realistis, pameran kekayaan bukan bukti, & sering pendapatan si pemengaruh justru dari biaya kelas & afiliasi, bukan dari trading itu sendiri"],answer:2,explain:"Waspadai model 'yang jualan adalah kelasnya, bukan hasilnya'. Trading jangka pendek berisiko tinggi & mayoritas pemula rugi.",hint:"Dari mana kemungkinan besar uang si pemengaruh berasal: trading, atau menjual kelas & afiliasi?"},
{n:82,type:"mcq",micro:"Kasus: FOMO aset viral",q:"Sebuah aset mendadak viral, harganya naik 300% dalam sebulan, & semua orang di media sosial membelinya. Pendekatan yang lebih bijak:",options:["Tidak ikut karena panik/FOMO; bila tertarik, pelajari dulu cara kerjanya, akui risikonya sangat tinggi, & hanya gunakan uang yang siap hilang total — bukan dana kebutuhan atau darurat","Masukkan seluruh tabungan sekarang agar tidak ketinggalan kenaikannya, karena harga yang sudah naik tiga kali lipat akan terus naik, sebagaimana biasanya, dan sayang bila dilewatkan","Berutang untuk membeli aset itu sebanyak mungkin selagi harganya naik, lalu jual saat orang lain ikut membeli dan harganya tinggi"],answer:0,explain:"Kenaikan tajam yang didorong euforia sering diikuti penurunan tajam. Keputusan dari rasa takut ketinggalan jarang berakhir baik.",hint:"Membeli karena paham & siap rugi, atau karena takut ketinggalan?"},
{n:83,type:"tf",micro:"Refleksi: sabar itu strategi",q:"Benar atau Salah: Dalam investasi jangka panjang, sering masuk-keluar pasar untuk menebak titik naik-turun terbukti lebih andal daripada sekadar sabar menyetor rutin & bertahan.",answer:false,explain:"Sebaliknya, bagi kebanyakan orang 'membosankan tapi konsisten' mengalahkan 'aktif tapi menebak-nebak'. Waktu di pasar biasanya lebih penting daripada mencoba mengatur waktu pasar.",hint:"Bertahan & rutin, atau sering masuk-keluar menebak titik?"},
{n:84,type:"mcq",micro:"Kasus: warisan mendadak",q:"Seseorang tanpa dana darurat & dengan utang berbunga tinggi tiba-tiba menerima uang cukup besar. Urutan langkah yang umumnya paling bijak:",options:["Belanjakan sebagian besar uang itu untuk barang mewah selagi ada, karena uang yang tiba-tiba datang tidak perlu dikelola secara khusus","Sisihkan dana darurat → lunasi utang berbunga tinggi → sisanya dipertimbangkan untuk investasi jangka panjang secara bertahap, setelah belajar & menentukan tujuan","Langsung investasikan seluruhnya di aset yang paling agresif, sebab dana darurat dan pelunasan utang bisa menyusul dari keuntungan investasinya"],answer:1,explain:"Uang besar mendadak paling aman dikelola pelan: amankan fondasi, hapus beban bunga tinggi, lalu tumbuhkan sisanya dengan rencana.",hint:"Fondasi & beban dulu, pertumbuhan kemudian — atau langsung agresif?"},
{n:85,type:"order",micro:"Memeriksa legalitas sebuah produk investasi",q:"Urutkan langkah sederhana memeriksa apakah sebuah produk/entitas investasi resmi.",items:["Catat nama lengkap perusahaan/produk & pihak yang menawarkan","Cek apakah terdaftar/berizin pada otoritas keuangan yang berwenang","Cari pemberitaan, ulasan, & daftar 'entitas ilegal' atau peringatan resmi terkait nama itu","Bila tidak terdaftar atau ada peringatan, jangan menaruh uang & ingatkan orang lain"],answer:[0,1,2,3],explain:"Identifikasi → cek izin resmi → cari peringatan → putuskan. Legalitas adalah saringan pertama sebelum menilai hal lain.",hint:"Apa yang perlu kamu ketahui persis sebelum bisa mengeceknya?"},
{n:86,type:"mcq",micro:"Kasus: menyeimbangkan tujuan ganda",q:"Sebuah keluarga ingin (1) punya dana darurat, (2) menyiapkan kuliah anak 12 tahun lagi, (3) liburan tahun depan. Pendekatan yang masuk akal:",options:["Semua tujuan didanai dari satu investasi saham agresif saja, supaya prosesnya sederhana dan keuntungannya bisa dibagi sesuai kebutuhan nanti","Semua tujuan ditunda sampai keluarga itu 'punya banyak uang', karena menyisihkan sedikit sekarang dianggap tidak akan berarti apa-apa","Bagi uang sesuai tujuan: dana darurat & liburan di tabungan aman; dana kuliah sebagian diinvestasikan jangka panjang & disetori rutin"],answer:2,explain:"Tiap tujuan punya horizon berbeda, jadi wadahnya berbeda. Memisahkan 'kantong' membuat keputusan lebih jelas & terlindungi.",hint:"Tujuan dekat ke tabungan, tujuan jauh sebagian ke investasi — atau semua ke satu tempat?"},
{n:87,type:"mcq",micro:"Kasus: bujukan 'rugi kalau tidak sekarang'",q:"Penjual berkata, 'Harga naik minggu depan, kalau tidak beli sekarang kamu rugi besar!' Ini...",options:["Taktik tekanan waktu; keputusan investasi yang baik tidak boleh dipaksa terburu-buru, & tidak ada yang tahu pasti harga minggu depan","Nasihat tulus yang harus segera diikuti, karena penjual yang mengingatkan soal kenaikan harga berniat baik dan tahu keadaannya","Jaminan bahwa harga naik minggu depan, sehingga membeli sekarang lebih menguntungkan daripada menunggu sambil membandingkan"],answer:0,explain:"Urgensi buatan adalah alat penjualan & penipuan. Peluang investasi yang sehat tidak hilang hanya karena kamu berpikir sehari lebih lama.",hint:"Apakah keputusan menaruh uang jangka panjang sebaiknya dibuat dalam tekanan 5 menit?"},
{n:88,type:"tf",micro:"Paham dulu baru masuk",q:"Benar atau Salah: Prinsip 'jangan berinvestasi pada sesuatu yang tidak kamu pahami' membantu melindungi dari produk yang tidak cocok maupun dari penipuan.",answer:true,explain:"Kalau kamu tidak bisa menjelaskan cara kerjanya, risikonya, & biayanya kepada orang lain, kemungkinan kamu belum siap menaruh uang di sana.",hint:"Bisakah kamu menjelaskan produk itu ke temanmu dengan yakin?"},
{n:89,type:"mcq",micro:"Kasus: menilai 'untung' Ponzi",q:"Sebuah program membayar 'imbal hasil' rutin 5%/bulan yang selalu mulus selama 8 bulan, lalu mulai menunda pembayaran & mendorong anggota merekrut lebih banyak orang. Ini menunjukkan...",options:["Bukti bahwa programnya menguntungkan dan laku keras, karena pembayaran lancar selama 8 bulan menunjukkan program terpercaya","Ciri khas skema Ponzi yang mulai kehabisan aliran uang anggota baru; segera hentikan setoran, tarik yang bisa ditarik, & laporkan","Sekadar gangguan sementara yang segera pulih, sehingga sebaiknya kamu menyetor lebih banyak lagi supaya pembayarannya cepat normal"],answer:1,explain:"Imbal hasil mulus & tinggi + dorongan rekrut + pembayaran mulai macet adalah pola kolaps Ponzi. Kerugian membesar bagi yang bertahan & merekrut.",hint:"Kenapa program 'menguntungkan' tiba-tiba butuh lebih banyak anggota baru & menunda bayar?"},
{n:90,type:"open",micro:"Analisis kasus menyeluruh",q:"Pak Budi (umur 40) baru bebas utang, punya dana darurat 6 bulan, bisa menyisihkan Rp3.000.000/bulan. Tujuannya: pensiun di umur 60 & dana kuliah anak 5 tahun lagi (butuh Rp100.000.000). Ia tergoda sebuah 'investasi' yang menjanjikan 8%/bulan dijamin. Beri analisis & saran langkah (tanpa menyebut produk spesifik).",explain:"Jawaban baik: (1) menolak & mengenali skema 8%/bulan 'dijamin' sebagai penipuan, cek legalitas; (2) memisahkan tujuan per horizon — kuliah 5 tahun ke instrumen aman/stabil dengan setoran ~Rp1.700.000/bulan, pensiun 20 tahun ke investasi jangka panjang terdiversifikasi dengan sisa dana; (3) menyebut otomatisasi, tinjau berkala, naikkan setoran, sesuaikan profil risiko & geser ke aman menjelang tenggat; (4) menjaga dana darurat tetap utuh; tanpa menyebut produk spesifik.",hint:"Tolak yang 'dijamin tinggi', lalu bagi uang menurut horizon tiap tujuan (5 tahun vs 20 tahun) dan hitung kebutuhan setoran kuliah.",sample:"Pertama, tolak 'investasi 8%/bulan dijamin' itu — setara ~150% per tahun yang 'pasti', jelas melanggar prinsip risiko-imbal hasil dan hampir pasti penipuan/Ponzi; cek legalitasnya dan jangan menaruh uang. Kedua, pisahkan dua tujuan berdasarkan horizon. Dana kuliah anak (5 tahun, butuh Rp100.000.000): 5 tahun tergolong menengah-pendek, jadi sebagian besar sebaiknya di instrumen aman/relatif stabil (tabungan berjangka, deposito, atau instrumen pendapatan tetap berrisiko rendah), dengan setoran rutin sekitar Rp100.000.000 ÷ 60 bulan ≈ Rp1.700.000/bulan; jangan mengandalkan pertumbuhan tinggi untuk horizon sependek ini. Ketiga, dana pensiun (20 tahun): sisa kemampuan menyisih (sekitar Rp1.300.000/bulan) cocok untuk investasi jangka panjang terdiversifikasi dan disetor rutin, karena 20 tahun memberi waktu bagi pertumbuhan dan pemulihan penurunan; komposisinya disesuaikan dengan profil risiko Pak Budi dan digeser lebih aman menjelang umur 58-60. Keempat, otomatiskan kedua setoran, tinjau setahun sekali, naikkan setoran saat penghasilan bertambah, dan pelajari lebih lanjut sebelum menambah jenis investasi. Kelima, pertahankan dana darurat 6 bulan itu tetap utuh dan terpisah."},
{n:91,type:"mcq",micro:"Kasus: semua uang di deposito untuk 30 tahun",q:"Seorang berumur 25 menaruh 100% dana pensiunnya (untuk 35 tahun lagi) di deposito berbunga rendah 'agar aman'. Kelemahan besar rencana ini:",options:["Deposito terlalu berisiko untuk jangka 35 tahun, sehingga dana pensiun sebaiknya disimpan tunai di rumah supaya aman dari penurunan nilai, walau uang tunai tergerus kenaikan harga dari tahun ke tahun","Tidak ada kelemahan, ini rencana ideal karena yang paling aman dianggap paling baik untuk jangka waktu berapa pun","Selama 35 tahun, bunga rendah kemungkinan kalah oleh inflasi, sehingga daya beli dana pensiun bisa jauh lebih kecil dari yang dibutuhkan — 'terlalu aman' pun berisiko untuk horizon sepanjang itu"],answer:2,explain:"Untuk horizon sangat panjang, sama sekali tidak berinvestasi pada aset pertumbuhan berisiko 'gagal secara perlahan' melawan inflasi. Keseimbangan yang tepat tetap bergantung profil risiko.",hint:"Apa yang terjadi pada daya beli dana yang hanya tumbuh 3% selama 35 tahun inflasi 4%?"},
{n:92,type:"tf",micro:"Tak ada untung besar tanpa risiko",q:"Benar atau Salah: Bila sebuah tawaran menjanjikan imbal hasil jauh di atas rata-rata pasar secara konsisten & 'tanpa risiko', itu adalah tanda peringatan kuat, bukan peluang langka.",answer:true,explain:"Prinsip ini adalah pelindung terbaik dari penipuan investasi. Imbal hasil luar biasa yang 'dijamin' hampir selalu berarti risiko disembunyikan atau tidak ada usaha nyata di baliknya.",hint:"Peluang emas, atau pelanggaran hukum risiko-imbal hasil?"},
{n:93,type:"mcq",micro:"Kasus: menunda investasi 5 tahun",q:"Dua orang berencana menyisihkan jumlah sama untuk 30 tahun. Orang A mulai sekarang; orang B menunggu 5 tahun 'sampai lebih siap'. Dampak paling mungkin bagi B:",options:["Kehilangan 5 tahun pertumbuhan berbunga di awal — untuk mengejar, B harus menyetor jauh lebih besar tiap bulan daripada A","B lebih untung karena 'lebih siap', sebab ia memulai dengan kondisi keuangan yang lebih matang dan menyetor lebih besar nantinya","Tidak ada bedanya, karena jumlah setoran yang sama selama 30 tahun menghasilkan nilai akhir yang setara bagi keduanya"],answer:0,explain:"Lima tahun pertama tampak tidak penting, tetapi itulah tahun yang punya waktu terlama untuk berbunga. Menunda 'sampai siap' berbiaya besar.",hint:"Tahun-tahun mana yang paling berharga bagi bunga majemuk: yang pertama atau yang terakhir?"},
{n:94,type:"mcq",micro:"Kasus: mengelola menang & kalah",q:"Selama 10 tahun berinvestasi jangka panjang, kamu akan mengalami beberapa tahun rugi & beberapa tahun untung besar. Sikap yang menopang hasil:",options:["Menjual semua investasinya di akhir setiap tahun lalu membeli lagi dari awal, supaya terhindar dari tahun-tahun yang mengalami kerugian","Tetap pada rencana & setoran rutin di kedua kondisi; tidak berhenti menyetor saat rugi & tidak menjadi serakah/menambah risiko berlebihan saat untung","Berhenti menyetor setiap kali rugi dan menaruh seluruh uang di aset paling berisiko setiap kali untung, supaya hasil lebih cepat besar"],answer:1,explain:"Konsistensi lintas siklus pasar — termasuk terus menyetor saat harga murah — adalah bagian penting dari hasil jangka panjang.",hint:"Reaksi berlebihan pada tiap tahun, atau tetap pada rencana melewati naik-turun?"},
{n:95,type:"tf",micro:"Investasi bukan judi (bila dilakukan benar)",q:"Benar atau Salah: Berinvestasi jangka panjang secara terdiversifikasi & rutin pada dasarnya sama dengan berjudi, karena keduanya sepenuhnya soal keberuntungan.",answer:false,explain:"Sebaliknya, investasi yang sehat menaruh modal pada kegiatan ekonomi nyata yang cenderung tumbuh dalam jangka panjang, dengan risiko yang dikelola lewat diversifikasi & horizon waktu. Judi adalah permainan berjumlah negatif yang dirancang agar pemain kalah. Namun 'trading' spekulatif jangka pendek bisa mendekati perilaku judi.",hint:"Menaruh modal pada ekonomi yang tumbuh dengan risiko terkelola, atau permainan yang dirancang agar pemain kalah?"},
{n:96,type:"mcq",micro:"Kasus: teman rugi lalu menyerah",q:"Temanmu menaruh semua uangnya di satu aset berisiko, rugi besar, lalu berkata 'investasi itu penipuan, mending uang dihabiskan saja'. Tanggapan yang seimbang:",options:["Setuju saja dengan temanmu, sebaiknya uang dihabiskan karena gagasan menyisihkan uang untuk masa depan itu terbukti merugikan banyak orang, termasuk dirimu sendiri","Sarankan ia berutang untuk 'balas dendam' di aset yang sama agar kerugian cepat tertutup, karena harganya segera naik kembali","Yang bermasalah adalah caranya (tanpa dana darurat, tanpa diversifikasi, horizon salah, mungkin produk mencurigakan), bukan gagasan menyisihkan uang untuk masa depan itu sendiri"],answer:2,explain:"Pelajaran dari kerugian: perbaiki proses (fondasi, diversifikasi, horizon, legalitas), bukan meninggalkan perencanaan keuangan sama sekali.",hint:"Yang salah gagasan menabung/investasinya, atau cara ia menjalankannya?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti tentang menabung vs investasi:",options:["Tabung untuk keamanan, dana darurat, & tujuan dekat; investasikan uang jangka panjang agar tumbuh melawan inflasi, dengan diversifikasi, setoran rutin, & biaya rendah; waspadai janji 'untung tinggi tanpa risiko' & mulai lebih awal","Habiskan uang yang kamu punya sekarang, karena menabung dan berinvestasi sama-sama kurang berguna dan hanya membuat hidup kurang menyenangkan, sehingga tak perlu repot merencanakan masa depan sejak sekarang","Taruh uangmu di satu aset yang paling banyak dibicarakan orang di media sosial, sebab aset yang ramai dibicarakan paling cepat naik nilainya, dan tak perlu menyebar uang ke aset lain"],answer:0,explain:"Ringkasan: dua alat untuk dua tujuan; fondasi dulu; pertumbuhan lewat diversifikasi, rutinitas, biaya rendah, & horizon; jauhi penipuan; waktu adalah sekutu.",hint:"Aman & cair untuk dekat, tumbuh & terdiversifikasi untuk jauh, mulai awal, hindari 'pasti untung' — rangkai."},
{n:98,type:"tf",micro:"Bukan nasihat personal",q:"Benar atau Salah: Pelajaran ini mengajarkan prinsip & konsep untuk memahami pilihan keuangan, tetapi keputusan investasi nyata tetap perlu disesuaikan dengan tujuan, kondisi, & profil risiko masing-masing orang.",answer:true,explain:"Materi edukatif ≠ rekomendasi produk. Sebelum memutuskan, pelajari lebih dalam & pertimbangkan situasi pribadimu; bila perlu, cari sumber tepercaya.",hint:"Konsep umum untuk memahami, atau perintah membeli produk tertentu untuk semua orang?"},
{n:99,type:"mcq",micro:"Kasus: mengajari kebiasaan",q:"Cara terbaik menanamkan kebiasaan finansial sehat pada anak/adik:",options:["Larang ia menyentuh uang sampai dewasa supaya tidak boros, karena anak belum bisa belajar mengelola uang di usianya sekarang, lalu ajari saat ia sudah bekerja","Latih memisahkan uang untuk 'dipakai sekarang', 'ditabung untuk tujuan', & 'disimpan lama/ditumbuhkan'; contohkan menyisihkan di awal & bersabar untuk tujuan","Beri yang ia minta agar ia senang dan tidak perlu belajar menunggu, sebab kebiasaan menunda hanya membuat anak merasa tertekan"],answer:1,explain:"Kebiasaan 'sisihkan dulu, bedakan tujuan berdasarkan waktu, & bersabar' lebih berharga diajarkan sejak dini daripada sekadar teori.",hint:"Melatih memilah & bersabar, atau memberi semua / melarang total?"},
{n:100,type:"open",micro:"Refleksi & rencana pribadi",q:"Tulis rencana pribadi 'menabung & investasi' untuk dirimu berisi minimal 5 poin, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 poin konkret dengan alasan, mencakup ide inti bab: bayar diri sendiri dulu, dana darurat sebelum investasi, pisahkan uang per horizon, investasi jangka panjang yang rutin-terdiversifikasi-biaya rendah-tidak panik, tolak 'untung tinggi tanpa risiko' & cek legalitas, mulai awal & naikkan setoran, tinjau berkala & amankan menjelang tenggat.",hint:"Ambil satu pelajaran dari tiap fase — kebiasaan menyisihkan, dana darurat, horizon, diversifikasi & kesabaran, waspada penipuan, mulai awal — dan ubah jadi 'aku akan...'.",sample:"Contoh rencana pribadi: (1) Aku akan 'membayar diri sendiri lebih dulu' — menyisihkan sebagian setiap kali menerima uang, sebelum dibelanjakan — supaya menabung jadi kebiasaan, bukan sisa. (2) Aku akan membangun dana darurat di tabungan yang aman & mudah diambil sebelum mulai berinvestasi — agar kejutan hidup tidak memaksaku berutang atau menjual investasi saat rugi. (3) Aku akan memisahkan uang berdasarkan kapan dipakai: tujuan dekat (di bawah ~2-3 tahun) ditabung, tujuan jauh diinvestasikan — karena horizon menentukan seberapa besar risiko yang pantas. (4) Untuk uang jangka panjang, aku akan berinvestasi rutin dengan jumlah tetap, terdiversifikasi, memilih biaya rendah, & tidak panik saat pasar turun — karena konsistensi, waktu, & bunga majemuk adalah inti pertumbuhan. (5) Aku akan menolak setiap tawaran 'untung tinggi tanpa risiko' & selalu mengecek legalitas serta memahami produk sebelum menaruh uang — karena itu ciri penipuan. (6) Aku akan mulai sedini mungkin walau jumlahnya kecil, & menaikkan setoran saat penghasilanku bertambah — karena tahun-tahun awal paling berharga & menghindari 'inflasi gaya hidup' mempercepat tujuan. (7) Aku akan meninjau rencana setahun sekali & menggeser dana ke lebih aman saat sebuah tujuan makin dekat."},
];
